from dataclasses import dataclass
from typing import Optional

@dataclass
class Record:
    camera_id: int
    c_prime: bytes
    n: int
    nonce: bytes
    ciphertext: bytes
    # Label of the crumpled block this record belongs to (entities/block_header.py), or
    # None for the original scheme, where each record carries its own, only puzzle.
    block: Optional[str] = None
    # Capture instant, generated by the camera (ISO-8601). Goes into the AES-GCM associated
    # data together with camera_id (crypto/signing.record_ad), so the ciphertext only opens
    # under the camera and instant it was captured at.
    captured_at: Optional[str] = None
    # ECDSA signature of the camera over every field above (crypto/signing.py).
    signature: Optional[bytes] = None
